-- Pune Division Teachers' Constituency (03) - Polling Station List
-- Source: Annexure 11-M, notice dated 12/10/2026 (District Election Officer, Pune)
SET NAMES utf8mb4;

CREATE DATABASE IF NOT EXISTS election_db
  CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE election_db;

DROP TABLE IF EXISTS polling_stations;
DROP TABLE IF EXISTS districts;

CREATE TABLE districts (
  id   TINYINT UNSIGNED NOT NULL PRIMARY KEY,
  name VARCHAR(50) NOT NULL UNIQUE
) ENGINE=InnoDB;

CREATE TABLE polling_stations (
  station_no  SMALLINT UNSIGNED NOT NULL PRIMARY KEY,
  district_id TINYINT UNSIGNED NOT NULL,
  location    VARCHAR(100) NOT NULL,   -- column 2: Location
  building    TEXT NOT NULL,           -- column 3: Polling Station Building
  area        TEXT NULL,               -- column 4: Polling Station Area (villages / localities)
  voter_type  ENUM('TEACHERS_ONLY','GRADUATES_ONLY','ALL_ELECTORS') NOT NULL, -- column 5
  constituency VARCHAR(80) NOT NULL DEFAULT '03 Pune Division Teachers'' Constituency',
  CONSTRAINT fk_ps_district FOREIGN KEY (district_id) REFERENCES districts(id),
  INDEX idx_ps_district (district_id),
  INDEX idx_ps_location (location)
) ENGINE=InnoDB;

USE election_db;
